import { button, badge, emptyState, escapeHtml as e, pageHeading } from "./ui.js";
import { icon } from "./icons.js";
import { select, panel, metric, table } from "./chairman.js";
import { boardingScope, boardingStudents, studentCards, activeStudentCard, visibleBoardingTrips, boardingRows, boardingSummary, tripReader, tripEvents, parentBoardingRows, boardingStatuses, boardingDirections, cardStatuses, boardingDate } from "./boarding-data.js";

const choices=(values,current)=>values.map(([id,name])=>`<option value="${e(id)}" ${String(id)===String(current)?"selected":""}>${e(name)}</option>`).join("");
const footer=(text)=>`<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel","close-dialog",{variant:"secondary"})}<button type="submit" class="button primary">${text}</button></footer>`;
const time=(value)=>value?new Intl.DateTimeFormat("en-LK",{timeZone:"Asia/Colombo",day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(new Date(value)):"—";
const tone=(status)=>status==="boarded"||status==="active"?"green":status==="not_boarded"||status==="lost"?"rose":status==="pending"||status==="unverified"?"amber":"neutral";
const statusBadge=(status)=>badge(e(boardingStatuses[status]||cardStatuses[status]||status),tone(status));
const demoNote=()=>`<div class="nfc-demo-note">${icon("spark",18)}<div><strong>NFC reader simulation</strong><p>Demonstrate card taps with browser-local records. Physical NFC readers and parent notifications are not connected.</p></div></div>`;
function cardView(options,scope){
  const query=options.boarding.query.trim().toLowerCase(),students=boardingStudents(options.state,options.context).filter((student)=>[student.name,student.admissionNumber,...studentCards(options.state,student.id).map((card)=>card.token)].join(" ").toLowerCase().includes(query));
  const featured=students.find((student)=>activeStudentCard(options.state,student.id)),card=featured?activeStudentCard(options.state,featured.id):null;
  return `<div class="nfc-card-intro"><div><span class="chairman-eyebrow">STUDENT TRANSPORT IDENTITY</span><h2>One student. One active transport card.</h2><p>Issue cards to school transport students, replace lost cards and preserve their boarding history.</p><label class="chairman-search">${icon("search",17)}<input type="search" aria-label="Search transport cards" data-change="nfc-query" data-focus="nfc-search" value="${e(options.boarding.query)}" placeholder="Student, admission or card code"></label></div>${card?`<article class="nfc-demo-card" aria-label="Sample transport NFC card"><div><img src="./assets/product-mark.svg" alt="School Management Platform"><span>TRANSPORT CARD<br><small>DEMO NFC</small></span></div><strong>${e(featured.name)}</strong><p>${e(featured.admissionNumber)} · Class ${e(featured.className)}</p><footer><span>${e(card.token)}</span>${icon("signal",30)}</footer></article>`:""}</div>`+panel("Transport card register","Card codes are demonstration identifiers. Replacing a card preserves its student and trip history.",students.length?table(["Student","School / bus","Card","Status","Actions"],students.map((student)=>{
    const latest=studentCards(options.state,student.id)[0],active=activeStudentCard(options.state,student.id),current=active||latest,bus=scope.buses.find((bus)=>bus.id===student.bus&&bus.branch===student.branch);
    return`<tr><td><strong>${e(student.name)}</strong><small>${e(student.admissionNumber)} · Class ${e(student.className)}</small></td><td>${e(options.state.branches.find((branch)=>branch.id===student.branch)?.name)}<small>${bus?"Bus "+e(bus.id):"No current bus allocation"}</small></td><td>${current?`<code>${e(current.token)}</code>`:"No card issued"}</td><td>${current?statusBadge(current.status):badge("Card needed","amber")}</td><td><div class="section-row-actions">${bus?button(current?"Replace card":"Issue card","nfc-card-issue",{value:student.id,variant:"secondary compact"}):"Allocate a bus before issuing"}${active?button("Lost / deactivate","nfc-card-disable",{value:active.id,variant:"secondary compact"}):""}${current?button("Card history","nfc-card-history",{value:student.id,variant:"secondary compact"}):""}</div></td></tr>`;
  }).join(""),"NFC transport card register"):emptyState("badge","No matching transport students","Allocate a student to a school bus, then issue their transport card."));
}
function readerView(options,scope,trip,rows){
  const reader=tripReader(options.state,trip);if(!reader)return emptyState("badge","Reader unavailable","This bus needs a demo reader record.");
  const cards=rows.map((row)=>({row,card:activeStudentCard(options.state,row.studentId)})).filter((item)=>item.card);
  return `<section class="surface nfc-reader-panel"><header><div><span class="chairman-eyebrow">BUS ${e(trip.busId)} READER</span><h2>Tap a transport card</h2><p>${e(reader.id)} · Demo device</p></div>${badge(reader.online?"Online":"Offline",reader.online?"green":"amber")}</header><div class="nfc-reader-target">${icon("signal",44)}<strong>${trip.phase==="boarding"?"Ready for a simulated tap":"Pickup window closed"}</strong><span>${reader.online?"Events update the trip register":"Taps queue locally until you reconnect"}</span></div>${options.boarding.feedback?.tripId===trip.id?`<div class="nfc-feedback feedback-${e(options.boarding.feedback.code)}" role="status">${e(options.boarding.feedback.message)}</div>`:""}${trip.phase==="boarding"?`<form data-form="nfc-tap" class="nfc-tap-form"><input type="hidden" name="tripId" value="${e(trip.id)}"><label class="field">Demo card code<input name="token" maxlength="40" placeholder="NET-NFC-0001" required autocapitalize="characters"></label><p class="form-error" role="alert" hidden></p><button type="submit" class="button primary">Simulate card tap</button></form>${cards.length?`<details class="nfc-demo-card-picker"><summary>Choose an expected student’s active card</summary><div>${cards.map(({row,card})=>`<button type="button" data-action="nfc-quick-tap" data-value="${e(trip.id)}|${e(card.token)}"><span><strong>${e(row.name)}</strong><small>${e(card.token)}</small></span>${icon("badge",18)}</button>`).join("")}</div></details>`:""}`:`<p class="chairman-filter-note">New taps are blocked. Queued taps captured before closure can still synchronise.</p>`}<div class="nfc-reader-tools">${button(reader.online?"Simulate offline":"Reconnect & sync",reader.online?"nfc-reader-offline":"nfc-reader-sync",{value:reader.id,variant:"secondary compact"})}${reader.online&&reader.queue.length?button("Sync queued taps","nfc-reader-sync",{value:reader.id,variant:"secondary compact"}):""}<span>${reader.queue.length} queued event${reader.queue.length===1?"":"s"}</span></div></section>`;
}
function tripRoster(options,scope,trip){
  const all=boardingRows(options.state,options.context,trip.id),summary=boardingSummary(all),query=options.boarding.query.trim().toLowerCase(),rows=all.filter((row)=>(options.boarding.status==="all"||row.status===options.boarding.status)&&(!query||[row.name,row.admission,row.className].join(" ").toLowerCase().includes(query))),reader=tripReader(options.state,trip),events=tripEvents(options.state,options.context,trip.id);
  return `<div class="nfc-trip-heading"><div><h2>Bus ${e(trip.busId)} · ${e(trip.route)}</h2><p>${e(trip.date)} · ${e(boardingDirections[trip.direction])} · Roster fixed when opened</p></div><div>${badge(trip.phase==="boarding"?"Pickup open":"Pickup closed",trip.phase==="boarding"?"green":"neutral")}${button("Download manifest CSV","nfc-manifest",{value:trip.id,variant:"secondary compact",iconName:"download"})}${scope.canReview&&trip.phase==="boarding"?button("Close pickup window","nfc-close-trip",{value:trip.id,variant:"secondary compact"}):""}</div></div><div class="nfc-counts">${Object.entries({expected:"Expected",boarded:"Boarded",pending:"Not yet boarded",unverified:"Needs review",not_boarded:"Not boarded",excused:"Not travelling"}).map(([key,label])=>`<div class="nfc-count-${key}"><strong>${summary[key]}</strong><span>${label}</span></div>`).join("")}</div>${!reader?.online||reader?.queue.length?`<div class="nfc-sync-warning">${icon("signal",20)}<p>Reader ${reader?.online?"has events awaiting sync":"is offline"}. Missing taps cannot confirm that a student did not board.</p></div>`:""}<div class="nfc-trip-grid"><div>${panel("Trip boarding register","Transport boarding is separate from the Class Teacher’s attendance register.",`<div class="chairman-list-tools">${select("Boarding status","nfc-status",[["all","All expected students"],...Object.entries(boardingStatuses)],options.boarding.status)}<label class="chairman-search">${icon("search",16)}<input type="search" aria-label="Search boarding roster" data-change="nfc-query" data-focus="nfc-search" value="${e(options.boarding.query)}" placeholder="Student or admission number"></label></div>`+(rows.length?table(["Expected student","Transport status","Recorded time","Actions"],rows.map((row)=>`<tr><td><strong>${e(row.name)}</strong><small>${e(row.admission)} · Class ${e(row.className)}</small></td><td>${statusBadge(row.status)}${row.source?`<small>${e(row.source)}</small>`:""}</td><td>${e(time(row.at))}</td><td><div class="section-row-actions">${scope.canReview?button("Review / correct","nfc-review",{value:trip.id+"|"+row.studentId,variant:"secondary compact"}):""}${scope.canOperate?button("Flag a concern","nfc-flag",{value:trip.id+"|"+row.studentId,variant:"secondary compact"}):badge("View access","neutral")}</div></td></tr>`).join(""),"NFC boarding roster"):emptyState("users","No roster entries match","Try another boarding status or student search.")))}</div>${scope.canOperate?readerView(options,scope,trip,all):`<section class="surface nfc-observer-note">${icon("badge",30)}<h2>Trip oversight</h2><p>Read the roster, exceptions and event history. The Transport Coordinator manages corrections and pickup closure.</p><p>Reader: ${e(reader?.id||"Unavailable")} · ${reader?.online?"Online":"Offline"}</p></section>`}</div>`+panel("Boarding event history","Append-only demo scan and correction history · Capture/sync times are shown in Sri Lanka time",events.length?`<div class="nfc-events">${events.map((event)=>{const student=trip.expected.find((entry)=>entry.studentId===event.studentId);return`<article class="nfc-event-${e(event.kind)}"><span>${icon(event.kind==="boarded"?"checkCircle":event.kind==="rejected"||event.kind==="exception"?"alert":"badge",20)}</span><div><strong>${e(event.message)}</strong><p>${student?e(student.name)+" · ":""}${e(event.by||"Demo reader")}</p>${event.reason?`<p class="nfc-event-reason">${e(event.reason)}</p>`:""}<small>Captured ${e(time(event.capturedAt||event.at))}${event.syncedAt?" · Synced "+e(time(event.syncedAt)):""}</small></div></article>`;}).join("")}</div>`:emptyState("badge","No boarding events yet","Simulate a card tap or flag a missed-card concern."));
}
function oversight(options,scope){
  if(!["chairman","principal","vice_principal"].includes(scope.context.role))return"";
  const trips=visibleBoardingTrips(options.state,options.context);
  return panel("School boarding coverage","All recorded accessible demo trips · Counts represent trip entries, not unique students",table(["School","Trip rosters","Expected boardings","Boarded","Needs review"],scope.branches.map((branch)=>{const selected=trips.filter((trip)=>trip.branch===branch.id),rows=selected.flatMap((trip)=>boardingRows(options.state,options.context,trip.id)),s=boardingSummary(rows);return`<tr><td>${e(branch.name)}</td><td>${selected.length}</td><td>${s.expected}</td><td>${s.boarded}</td><td>${s.unverified}</td></tr>`;}).join(""),"School NFC boarding coverage"));
}
function parentView(options,scope){
  const rows=parentBoardingRows(options.state,options.context),child=scope.child,latest=rows[0],card=activeStudentCard(options.state,child.id);
  return pageHeading("My bus boarding","Transport updates for "+child.name)+demoNote()+`<section class="surface nfc-parent-current"><div class="nfc-parent-icon">${icon("badge",32)}</div><div><span class="chairman-eyebrow">${e(child.admissionNumber)} · CLASS ${e(child.className)}</span><h2>${latest?e(boardingStatuses[latest.status]):"No boarding trip recorded yet"}</h2><p>${latest?"Bus "+e(latest.busId)+" · "+e(latest.route)+" · "+e(boardingDirections[latest.direction]):"Your child’s assigned trip updates will appear here."}</p>${latest?`<p>Trip date ${e(latest.date)}${latest.at?" · Recorded "+e(time(latest.at)):""}</p>`:""}<small>Transport card: ${card?"Active":"Contact the school office"}</small></div></section>${latest&&(!latest.readerOnline||latest.pendingSync)?`<div class="nfc-sync-warning">${icon("signal",20)}<p>The bus reader is awaiting synchronisation. Your child's latest scan may not be visible yet.</p></div>`:""}`+panel("Boarding history","Only this admission-selected child · Classroom attendance is recorded separately",rows.length?`<div class="nfc-parent-history">${rows.map((row)=>`<article><div><strong>Bus ${e(row.busId)} · ${e(boardingDirections[row.direction])}</strong><small>${e(row.date)}${row.at?" · Recorded "+e(time(row.at)):""}</small></div>${statusBadge(row.status)}</article>`).join("")}</div>`:emptyState("bus","Waiting for a trip roster","The school opens the roster for your child’s bus before boarding."));
}
export function boardingPage(options){
  const scope=boardingScope(options.state,options.context);if(!scope)return emptyState("badge","No boarding workspace access","Use an authorised school or parent appointment.");
  if(scope.child)return parentView(options,scope);
  const f=options.boarding,trips=visibleBoardingTrips(options.state,options.context).filter((trip)=>trip.busId===f.busId),trip=trips.find((trip)=>trip.id===f.tripId);
  return `<section class="nfc-workspace">${pageHeading(scope.context.role==="admin"?"NFC transport cards":"NFC bus boarding","Student transport cards, trip manifests and boarding events.",scope.canOperate&&scope.buses.length?button("Open trip roster","nfc-new-trip",{iconName:"plus"}):"")}${demoNote()}${scope.canCards&&scope.canRoster?`<div class="nfc-tabs" role="group" aria-label="NFC workspace views">${button("Trip boarding","nfc-tab",{value:"trips",variant:f.tab==="trips"?"primary":"secondary",extra:`aria-pressed="${f.tab==="trips"}"`})}${button("Transport cards","nfc-tab",{value:"cards",variant:f.tab==="cards"?"primary":"secondary",extra:`aria-pressed="${f.tab==="cards"}"`})}</div>`:""}${f.tab==="cards"?cardView(options,scope):oversight(options,scope)+`<div class="chairman-filters nfc-trip-filters">${select("School bus","nfc-bus",scope.buses.map((bus)=>[bus.id,(scope.branches.length>1?options.state.branches.find((branch)=>branch.id===bus.branch)?.name+" · ":"")+"Bus "+bus.id+" · "+bus.name]),f.busId)}${select("Trip roster","nfc-trip",trips.length?trips.map((trip)=>[trip.id,trip.date+" · "+boardingDirections[trip.direction]+" · "+(trip.phase==="boarding"?"Open":"Closed")]):[["","No trip roster yet"]],f.tripId)}</div>`+(trip?tripRoster(options,scope,trip):`<section class="surface">${emptyState("badge","No boarding roster for this bus",scope.canOperate?"Open a trip roster using the bus’s current student allocations, then demonstrate a card tap.":"The bus’s Transport Coordinator opens its expected roster.")}</section>`)}</section>`;
}
export function boardingTripForm(options){
  const scope=boardingScope(options.state,options.context);
  return`<form data-form="nfc-create-trip"><div class="form-body"><label class="field">School bus<select name="busId" required>${choices(scope.buses.map((bus)=>[bus.id,"Bus "+bus.id+" · "+bus.name]),options.boarding.busId)}</select></label><label class="field">Trip date<input name="date" type="date" min="2026-11-20" max="2026-11-27" value="${boardingDate()}" required></label><label class="field">Direction<select name="direction">${choices(Object.entries(boardingDirections),"to_school")}</select></label><p class="chairman-filter-note">The roster captures this bus’s current school student allocations. One pickup window can be open per bus; creating a roster does not start the simulated bus trip.</p></div>${footer("Open boarding roster")}</form>`;
}
export function boardingCardForm(options,student){
  const previous=activeStudentCard(options.state,student.id)||studentCards(options.state,student.id).find((card)=>card.status!=="replaced"),token="NET-NFC-"+crypto.randomUUID().slice(0,8).toUpperCase();
  return`<form data-form="nfc-issue-card"><div class="form-body"><input type="hidden" name="studentId" value="${e(student.id)}"><input type="hidden" name="previousId" value="${e(previous?.id||"")}"><h3>${e(student.name)}</h3><p>${e(student.admissionNumber)} · Class ${e(student.className)}</p>${previous?`<p class="chairman-filter-note">Previous card ${e(previous.token)} will be replaced. Past boarding records stay with this student.</p>`:""}<label class="field">Demo card code<input name="token" value="${e(token)}" maxlength="40" required></label><label class="field">Issue / replacement reason<textarea name="reason" rows="3" maxlength="500" required></textarea></label></div>${footer(previous?"Issue replacement card":"Issue transport card")}</form>`;
}
export function boardingDisableForm(card){
  return`<form data-form="nfc-disable-card"><div class="form-body"><input type="hidden" name="cardId" value="${e(card.id)}"><h3>${e(card.token)}</h3><label class="field">Card status<select name="status">${choices([["lost","Lost card"],["inactive","Deactivate card"]],"lost")}</select></label><label class="field">Reason<textarea name="reason" rows="3" maxlength="500" required></textarea></label></div>${footer("Deactivate card")}</form>`;
}
export function boardingReviewForm(options,tripId,studentId,flag=false){
  const row=boardingRows(options.state,options.context,tripId).find((row)=>row.studentId===studentId);
  return`<form data-form="${flag?"nfc-flag":"nfc-correct"}"><div class="form-body"><input type="hidden" name="tripId" value="${e(tripId)}"><input type="hidden" name="studentId" value="${e(studentId)}"><h3>${e(row.name)}</h3><p>${e(row.admission)} · Current status: ${e(boardingStatuses[row.status])}</p>${flag?"":`<label class="field">Reviewed transport status<select name="status">${choices(["boarded","unverified","excused","not_boarded"].map((status)=>[status,boardingStatuses[status]]),row.status==="pending"?"unverified":row.status)}</select></label>`}<label class="field">${flag?"Boarding concern":"Correction reason"}<textarea name="reason" rows="4" maxlength="500" required></textarea></label><p class="chairman-filter-note">${flag?"Flag a missed card, scan or boarding concern for the Transport Coordinator. This does not confirm boarding.":"Confirm not boarded only after pickup closes and the reader is online with no queued taps. The original history is retained; classroom attendance is unchanged."}</p></div>${footer(flag?"Record boarding concern":"Save reviewed status")}</form>`;
}
export function boardingCardHistory(options,student){
  return`<div class="form-body"><h3>${e(student.name)} · Card history</h3><div class="nfc-events">${studentCards(options.state,student.id).map((card)=>`<article><div><strong>${e(card.token)} · ${e(cardStatuses[card.status])}</strong><small>Issued ${e(time(card.issuedAt))} · ${e(card.issuedBy)}</small>${card.changes.map((change)=>`<p>${e(change.action)} · ${e(change.reason)}</p><small>${e(change.by)} · ${e(time(change.at))}</small>`).join("")}</div></article>`).join("")}</div></div><footer class="dialog-actions">${button("Close","close-dialog",{variant:"secondary"})}</footer>`;
}
